//! References built from marker fields: tables of figures (`TOC \c` / `\a` over caption
//! `SEQ` fields, ECMA-376 Part 1, §17.16.5.68), indexes (§17.16.5.29 INDEX over
//! §17.16.5.72 XE entries), tables of authorities (§17.16.5.67 TOA over §17.16.5.62 TA
//! citations), marking entries and citations, and converting footnotes ↔ endnotes
//! (§17.11.14 footnoteReference, §17.11.7 endnoteReference).
//!
//! The field results are regenerated by [`crate::fields::update`] with the page number
//! of every body paragraph from the layout.

use crate::collate::vi_cmp;
use crate::fields::{self, display_text, field_args, field_kind};
use crate::para::{self, Atom};
use crate::{
    para_clone, para_len, path_of, split_path, EditError, Op, Pos, Result, Selection, Session,
};
use bo_model::index::{body_paragraphs, para_at, para_index_text};
use bo_model::{
    Block, Document, HeaderFooter, ParaProps, Paragraph, RunContent, RunProps, Section,
    SectionBreak, TabAlign, TabLeader, TabStop, Twips, VertAlign,
};
use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::collections::HashMap;
use unicode_normalization::UnicodeNormalization;

// ---------------------------------------------------------------------------
// Field instructions
// ---------------------------------------------------------------------------

/// A parsed field instruction: positional arguments after the field name and switches
/// (`\x`, lower-cased) with their argument when the switch takes one.
struct Instr {
    args: Vec<String>,
    switches: Vec<(String, Option<String>)>,
}

impl Instr {
    /// Parse `instr`; the switches in `with_arg` take the following word as argument.
    fn parse(instr: &str, with_arg: &[&str]) -> Instr {
        let words = field_args(instr);
        let mut args = Vec::new();
        let mut switches = Vec::new();
        let mut i = 1;
        while i < words.len() {
            let w = &words[i];
            if w.starts_with('\\') && w.len() >= 2 {
                let name = w.to_ascii_lowercase();
                let arg = if with_arg.contains(&name.as_str()) {
                    words
                        .get(i + 1)
                        .filter(|n| !(n.starts_with('\\') && n.len() == 2))
                        .cloned()
                } else {
                    None
                };
                if arg.is_some() {
                    i += 1;
                }
                switches.push((name, arg));
            } else {
                args.push(w.clone());
            }
            i += 1;
        }
        Instr { args, switches }
    }

    fn has(&self, s: &str) -> bool {
        self.switches.iter().any(|(n, _)| n == s)
    }

    fn get(&self, s: &str) -> Option<&str> {
        self.switches
            .iter()
            .find(|(n, _)| n == s)
            .and_then(|(_, a)| a.as_deref())
    }
}

/// Caption label of a table of figures: `TOC \c "label"` (with label and number) or
/// `TOC \a "label"` (caption text only), §17.16.5.68.
pub(crate) fn figure_label(instr: &str) -> Option<(String, bool)> {
    let t = Instr::parse(instr, &["\\a", "\\c"]);
    if let Some(l) = t.get("\\c").filter(|l| !l.trim().is_empty()) {
        return Some((l.trim().to_owned(), true));
    }
    t.get("\\a")
        .filter(|l| !l.trim().is_empty())
        .map(|l| (l.trim().to_owned(), false))
}

/// The caption label (`SEQ label`, §17.16.5.56) of a paragraph and its text after the
/// number (separators `: . - – —` left out).
pub(crate) fn caption_of(atoms: &[Atom]) -> Option<(String, String)> {
    let (instr, _, end) = fields::para_fields(atoms)
        .into_iter()
        .find(|(i, _, _)| field_kind(i) == "SEQ")?;
    let label = field_args(&instr).get(1)?.clone();
    let after = display_text(atoms.get(end + 1..).unwrap_or_default());
    let after = after
        .trim_start_matches(|c: char| c.is_whitespace() || ":.-–—".contains(c))
        .trim_end()
        .to_owned();
    Some((label, after))
}

// ---------------------------------------------------------------------------
// Collected marks
// ---------------------------------------------------------------------------

/// A table of contents / figures target: a heading or a caption with its `_Toc` bookmark.
#[derive(Debug, Clone)]
pub(crate) struct Target {
    /// Heading level 1–9.
    pub level: Option<u8>,
    /// Caption label and caption text after the number.
    pub caption: Option<(String, String)>,
    /// Displayed paragraph text.
    pub text: String,
    /// `_Toc` bookmark name.
    pub name: String,
    /// Displayed page number (0 = unknown).
    pub page: u32,
}

/// An entry (XE) or citation (TA) field in body paragraph `pid`.
#[derive(Debug, Clone)]
pub(crate) struct FieldMark {
    pub instr: String,
    pub pid: usize,
}

/// XE and TA fields of the body outside the paragraphs `skip` says (generated results).
pub(crate) fn collect_marks(doc: &Document, skip: &dyn Fn(&[usize]) -> bool) -> Vec<FieldMark> {
    let mut out = Vec::new();
    for (pid, path) in body_paragraphs(doc).iter().enumerate() {
        if skip(path) {
            continue;
        }
        let Some(p) = para_at(doc, path) else {
            continue;
        };
        for (instr, _, _) in fields::para_fields(&para::flatten(p)) {
            if matches!(field_kind(&instr).as_str(), "XE" | "TA") {
                out.push(FieldMark { instr, pid });
            }
        }
    }
    out
}

/// Bookmarks of the main text: name → (paragraph of its start, paragraph of its end)
/// (§17.13.6.2 bookmarkStart, §17.13.6.1 bookmarkEnd).
pub(crate) fn bookmark_spans(doc: &Document) -> HashMap<String, (usize, usize)> {
    let mut out = HashMap::new();
    let mut open: HashMap<String, (String, usize)> = HashMap::new();
    for (pid, path) in body_paragraphs(doc).iter().enumerate() {
        let Some(p) = para_at(doc, path) else {
            continue;
        };
        for (_, name, id) in fields::bookmark_marks(&para::flatten(p)) {
            match name {
                Some(n) => {
                    open.insert(id, (n, pid));
                }
                None => {
                    if let Some((n, s)) = open.remove(&id) {
                        out.insert(n, (s, pid));
                    }
                }
            }
        }
    }
    for (n, s) in open.into_values() {
        out.entry(n).or_insert((s, s));
    }
    out
}

// ---------------------------------------------------------------------------
// Entry paragraphs
// ---------------------------------------------------------------------------

/// Where page numbers of generated entries are aligned: the right tab stop at the text
/// (or column) width and its leader.
#[derive(Debug, Clone, Copy)]
pub(crate) struct EntryLayout {
    pub width: i32,
    pub leader: TabLeader,
}

/// The leader of the right tab stop of a field's first paragraph (kept by updates; dots
/// when there is none).
pub(crate) fn leader_of(p: &Paragraph) -> TabLeader {
    p.props
        .tabs
        .as_ref()
        .and_then(|t| t.iter().rev().find(|t| t.align == TabAlign::Right))
        .map_or(TabLeader::Dot, |t| t.leader)
}

fn need(styles: &mut Vec<String>, id: &str) {
    if !styles.iter().any(|s| s == id) {
        styles.push(id.to_owned());
    }
}

/// An entry paragraph of `style`; a right tab stop (§17.3.1.37) when it holds a tab.
fn entry(style: &str, atoms: Vec<Atom>, lay: EntryLayout, styles: &mut Vec<String>) -> Paragraph {
    need(styles, style);
    let tab = atoms.iter().any(|(_, c)| matches!(c, RunContent::Tab));
    Paragraph::new(
        ParaProps {
            style: Some(style.to_owned()),
            tabs: tab.then(|| {
                vec![TabStop {
                    pos: Twips(lay.width),
                    align: TabAlign::Right,
                    leader: lay.leader,
                }]
            }),
            ..ParaProps::default()
        },
        para::rebuild(atoms),
    )
}

fn plain(s: &str) -> Vec<Atom> {
    para::text_atoms(s, &RunProps::default())
}

/// A location of an index entry or a citation.
#[derive(Debug, Clone, PartialEq)]
enum Loc {
    Page(u32),
    /// Pages of a bookmarked range (`\r`).
    Range(u32, u32),
    /// Cross-reference text instead of a page number (XE `\t`).
    See(String),
}

#[derive(Debug, Clone)]
struct Ref {
    loc: Loc,
    bold: bool,
    italic: bool,
}

/// Page (or bookmarked page range, `\r bookmark`) of a mark.
fn loc_of(
    sw: &Instr,
    pid: usize,
    spans: &HashMap<String, (usize, usize)>,
    page: &dyn Fn(usize) -> u32,
) -> Loc {
    if let Some((s, e)) = sw.get("\\r").and_then(|b| spans.get(b)) {
        let (a, b) = (page(*s), page(*e));
        if a != b && a > 0 && b > 0 {
            return Loc::Range(a.min(b), a.max(b));
        }
        return Loc::Page(a.max(b));
    }
    Loc::Page(page(pid))
}

/// Page locations sorted, unknown pages left out, duplicates merged (bold / italic kept).
fn page_refs(refs: &[Ref]) -> Vec<Ref> {
    let mut v: Vec<Ref> = Vec::new();
    for r in refs {
        let key = match r.loc {
            Loc::Page(0) | Loc::See(_) => continue,
            Loc::Page(p) => (p, p),
            Loc::Range(a, b) => (a, b),
        };
        if let Some(x) = v.iter_mut().find(|x| x.loc == r.loc) {
            x.bold |= r.bold;
            x.italic |= r.italic;
            continue;
        }
        let at = v
            .iter()
            .position(|x| {
                let k = match x.loc {
                    Loc::Range(a, b) => (a, b),
                    Loc::Page(p) => (p, p),
                    Loc::See(_) => (u32::MAX, u32::MAX),
                };
                k > key
            })
            .unwrap_or(v.len());
        v.insert(at, r.clone());
    }
    v
}

/// Page numbers joined by `list_sep`, ranges written `a{range_sep}b`; bold / italic page
/// numbers as marked (`\b`, `\i`).
fn pages_atoms(refs: &[Ref], list_sep: &str, range_sep: &str) -> Vec<Atom> {
    let mut out = Vec::new();
    for (i, r) in refs.iter().enumerate() {
        if i > 0 {
            out.extend(plain(list_sep));
        }
        let text = match &r.loc {
            Loc::Page(p) => p.to_string(),
            Loc::Range(a, b) => format!("{a}{range_sep}{b}"),
            Loc::See(s) => s.clone(),
        };
        let props = RunProps {
            bold: r.bold.then_some(true),
            italic: r.italic.then_some(true),
            ..RunProps::default()
        };
        out.extend(para::text_atoms(&text, &props));
    }
    out
}

// ---------------------------------------------------------------------------
// Tables of contents and of figures (§17.16.5.68)
// ---------------------------------------------------------------------------

/// Entries of a TOC field: headings (`\o`), or captions of one label (`\c` / `\a`).
/// `\h` hyperlinks, `\n` no page numbers (all levels or a level range), `\p` separator
/// instead of the right-aligned tab.
pub(crate) fn toc(
    instr: &str,
    targets: &[Target],
    lay: EntryLayout,
    styles: &mut Vec<String>,
) -> Vec<Paragraph> {
    let sw = Instr::parse(
        instr,
        &[
            "\\a", "\\b", "\\c", "\\d", "\\f", "\\l", "\\n", "\\o", "\\p", "\\s", "\\t",
        ],
    );
    let link = sw.has("\\h");
    let sep = sw.get("\\p").map(str::to_owned);
    let no_pages = |level: u8| {
        sw.has("\\n")
            && sw.get("\\n").is_none_or(|r| {
                let mut it = r.split('-').map(|x| x.trim().parse::<u8>().ok());
                match (it.next(), it.next()) {
                    (Some(Some(a)), Some(Some(b))) => (a..=b).contains(&level),
                    (Some(Some(a)), None) => a == level,
                    _ => true,
                }
            })
    };
    let line = |style: &str, text: &str, t: &Target, show_page: bool, styles: &mut Vec<String>| {
        let props = RunProps {
            link: link.then(|| format!("#{}", t.name)),
            ..RunProps::default()
        };
        let mut atoms = para::text_atoms(text, &props);
        if show_page {
            match &sep {
                Some(s) => atoms.extend(para::text_atoms(s, &props)),
                None => atoms.push((props.clone(), RunContent::Tab)),
            }
            atoms.push((
                props.clone(),
                RunContent::Field {
                    instr: format!("PAGEREF {} \\h", t.name),
                    cached: if t.page > 0 {
                        t.page.to_string()
                    } else {
                        String::new()
                    },
                    locked: false,
                    codes: false,
                },
            ));
        }
        let mut p = entry(style, atoms, lay, styles);
        // The right tab stays on every entry of a table of contents (page numbers align).
        if p.props.tabs.is_none() && sep.is_none() {
            p.props.tabs = Some(vec![TabStop {
                pos: Twips(lay.width),
                align: TabAlign::Right,
                leader: lay.leader,
            }]);
        }
        p
    };
    let mut out = Vec::new();
    if let Some((label, with_label)) = figure_label(instr) {
        for t in targets {
            let Some((l, after)) = &t.caption else {
                continue;
            };
            if !l.eq_ignore_ascii_case(&label) && l.to_lowercase() != label.to_lowercase() {
                continue;
            }
            let text = if with_label { &t.text } else { after };
            if text.is_empty() {
                continue;
            }
            out.push(line("TableofFigures", text, t, !no_pages(1), styles));
        }
    } else {
        let (lo, hi) = fields::toc_levels(instr);
        for t in targets {
            let Some(level) = t.level.filter(|l| (lo..=hi).contains(l)) else {
                continue;
            };
            out.push(line(
                &format!("TOC{level}"),
                &t.text,
                t,
                !no_pages(level),
                styles,
            ));
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Indexes (§17.16.5.29 INDEX, §17.16.5.72 XE)
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
struct Node {
    text: String,
    refs: Vec<Ref>,
    kids: Vec<Node>,
}

fn add_entry(nodes: &mut Vec<Node>, levels: &[String], r: Ref) {
    let Some((first, rest)) = levels.split_first() else {
        return;
    };
    let i = if let Some(i) = nodes.iter().position(|n| &n.text == first) {
        i
    } else {
        nodes.push(Node {
            text: first.clone(),
            refs: Vec::new(),
            kids: Vec::new(),
        });
        nodes.len() - 1
    };
    if rest.is_empty() {
        nodes[i].refs.push(r);
    } else {
        add_entry(&mut nodes[i].kids, rest, r);
    }
}

/// Letters without any diacritic, lower case (`đ` → `d`).
fn fold(s: &str) -> String {
    s.nfd()
        .filter(|c| !('\u{0300}'..='\u{036F}').contains(c))
        .map(|c| match c {
            'đ' | 'Đ' => 'd',
            c => c.to_lowercase().next().unwrap_or(c),
        })
        .collect()
}

/// Sort order of index entries: Vietnamese dictionary order (`a ă â … d đ …`, then tones
/// ngang, huyền, hỏi, ngã, sắc, nặng) or, for another language, letters without
/// diacritics first.
fn entry_cmp(a: &str, b: &str, vi: bool) -> Ordering {
    if vi {
        vi_cmp(a, b)
    } else {
        fold(a).cmp(&fold(b)).then_with(|| vi_cmp(a, b))
    }
}

fn sort_nodes(nodes: &mut [Node], vi: bool) {
    nodes.sort_by(|a, b| entry_cmp(&a.text, &b.text, vi));
    for n in nodes {
        sort_nodes(&mut n.kids, vi);
    }
}

/// The alphabetic group of an entry: its first letter in upper case — in Vietnamese
/// `Ă Â Đ Ê Ô Ơ Ư` are letters of their own, other languages group by the base letter;
/// digits and symbols form one group `#`.
pub fn group_letter(text: &str, vi: bool) -> String {
    let Some(c) = text.trim().chars().next() else {
        return "#".into();
    };
    if !c.is_alphabetic() {
        return "#".into();
    }
    if matches!(c, 'đ' | 'Đ') {
        return if vi { "Đ" } else { "D" }.into();
    }
    let mut d = c.to_string().nfd().collect::<Vec<char>>().into_iter();
    let base = d.next().unwrap_or(c);
    let mut s = String::from(base);
    if vi {
        // Breve (ă), circumflex (â ê ô) and horn (ơ ư) make letters; tones do not.
        s.extend(d.filter(|m| matches!(m, '\u{0306}' | '\u{0302}' | '\u{031B}')));
    }
    s.nfc().collect::<String>().to_uppercase()
}

/// `\p "a-m"`: the entries whose first letter lies in the range.
fn letter_in(range: &str, text: &str) -> bool {
    let mut it = range.split('-').map(|x| fold(x.trim()).chars().next());
    let (Some(Some(lo)), Some(Some(hi))) = (it.next(), it.next()) else {
        return true;
    };
    fold(text.trim())
        .chars()
        .next()
        .is_some_and(|c| (lo..=hi).contains(&c))
}

/// Separators of an index or table of authorities.
struct Seps {
    /// Entry → page numbers (`\e`).
    entry: String,
    /// Between page numbers (`\l`).
    list: String,
    /// Page range (`\g`).
    range: String,
    /// Entry → cross-reference (`\k`).
    see: String,
}

/// Text of an index entry with its page numbers and cross-references.
fn node_atoms(n: &Node, s: &Seps, entry_sep: &str) -> Vec<Atom> {
    let mut a = plain(&n.text);
    let pages = page_refs(&n.refs);
    if !pages.is_empty() {
        a.extend(plain(entry_sep));
        a.extend(pages_atoms(&pages, &s.list, &s.range));
    }
    let sees: Vec<&Ref> = n
        .refs
        .iter()
        .filter(|r| matches!(r.loc, Loc::See(_)))
        .collect();
    for (i, r) in sees.iter().enumerate() {
        a.extend(plain(if i == 0 { &s.see } else { "; " }));
        if let Loc::See(t) = &r.loc {
            let props = RunProps {
                bold: r.bold.then_some(true),
                italic: r.italic.then_some(true),
                ..RunProps::default()
            };
            a.extend(para::text_atoms(t, &props));
        }
    }
    a
}

fn run_in_atoms(n: &Node, s: &Seps, a: &mut Vec<Atom>) {
    // Sub-entries share the line: a tab separator would not line up, a comma does.
    let sep = if s.entry.contains('\t') {
        ", "
    } else {
        s.entry.as_str()
    };
    a.extend(node_atoms(n, s, sep));
    if !n.kids.is_empty() {
        a.extend(plain(": "));
        for (i, k) in n.kids.iter().enumerate() {
            if i > 0 {
                a.extend(plain("; "));
            }
            run_in_atoms(k, s, a);
        }
    }
}

fn indented(
    n: &Node,
    level: usize,
    s: &Seps,
    lay: EntryLayout,
    out: &mut Vec<Paragraph>,
    styles: &mut Vec<String>,
) {
    let style = format!("Index{}", level.min(9));
    out.push(entry(&style, node_atoms(n, s, &s.entry), lay, styles));
    for k in &n.kids {
        indented(k, level + 1, s, lay, out, styles);
    }
}

/// Entries of an INDEX field from the XE fields: `XE "main:sub"` levels, `\b` / `\i`
/// bold / italic page number, `\r bookmark` page range, `\t "text"` cross-reference,
/// `\f type` entry type. INDEX switches: `\b bookmark` (entries inside it), `\e` / `\l` /
/// `\g` / `\k` separators, `\f type`, `\h "A"` group headings (`A` stands for the letter;
/// a blank argument: an empty line), `\p "a-m"` letters, `\r` run-in sub-entries,
/// `\z LCID` language (1066 = Vietnamese order). `\c` columns are the section's (set when
/// the index is inserted).
pub(crate) fn index(
    instr: &str,
    marks: &[FieldMark],
    spans: &HashMap<String, (usize, usize)>,
    page: &dyn Fn(usize) -> u32,
    lay: EntryLayout,
    vi_default: bool,
    styles: &mut Vec<String>,
) -> Vec<Paragraph> {
    let ix = Instr::parse(
        instr,
        &[
            "\\b", "\\c", "\\d", "\\e", "\\f", "\\g", "\\h", "\\k", "\\l", "\\p", "\\s", "\\z",
        ],
    );
    // LCID 1066 (0x042A) = Vietnamese ([MS-LCID]).
    let vi = ix.get("\\z").map_or(vi_default, |z| z.trim() == "1066");
    let ftype = ix.get("\\f").unwrap_or("I");
    let within = ix.get("\\b").and_then(|b| spans.get(b)).copied();
    let mut tree: Vec<Node> = Vec::new();
    for m in marks.iter().filter(|m| field_kind(&m.instr) == "XE") {
        if within.is_some_and(|(s, e)| m.pid < s || m.pid > e) {
            continue;
        }
        let xe = Instr::parse(&m.instr, &["\\f", "\\r", "\\t", "\\y"]);
        let Some(text) = xe.args.first() else {
            continue;
        };
        if !xe.get("\\f").unwrap_or("I").eq_ignore_ascii_case(ftype) {
            continue;
        }
        let levels: Vec<String> = text
            .split(':')
            .map(|l| l.trim().to_owned())
            .filter(|l| !l.is_empty())
            .collect();
        let Some(main) = levels.first() else {
            continue;
        };
        if ix.get("\\p").is_some_and(|r| !letter_in(r, main)) {
            continue;
        }
        let loc = match xe.get("\\t") {
            Some(t) => Loc::See(t.to_owned()),
            None => loc_of(&xe, m.pid, spans, page),
        };
        add_entry(
            &mut tree,
            &levels,
            Ref {
                loc,
                bold: xe.has("\\b"),
                italic: xe.has("\\i"),
            },
        );
    }
    sort_nodes(&mut tree, vi);
    let seps = Seps {
        entry: ix.get("\\e").unwrap_or(", ").to_owned(),
        list: ix.get("\\l").unwrap_or(", ").to_owned(),
        range: ix.get("\\g").unwrap_or("\u{2013}").to_owned(),
        see: ix.get("\\k").unwrap_or(". ").to_owned(),
    };
    let heading = ix
        .has("\\h")
        .then(|| ix.get("\\h").unwrap_or("").to_owned());
    let mut out = Vec::new();
    let mut group: Option<String> = None;
    for n in &tree {
        if let Some(h) = &heading {
            let g = group_letter(&n.text, vi);
            if group.as_ref() != Some(&g) {
                let text = if h.contains('A') {
                    h.replacen('A', &g, 1)
                } else {
                    h.trim().to_owned()
                };
                out.push(entry("IndexHeading", plain(&text), lay, styles));
                group = Some(g);
            }
        }
        if ix.has("\\r") {
            let mut a = Vec::new();
            run_in_atoms(n, &seps, &mut a);
            out.push(entry("Index1", a, lay, styles));
        } else {
            indented(n, 1, &seps, lay, &mut out, styles);
        }
    }
    out
}

// ---------------------------------------------------------------------------
// Tables of authorities (§17.16.5.67 TOA, §17.16.5.62 TA)
// ---------------------------------------------------------------------------

/// Heading of a citation category (`TA \c n`, 1–16) in a table of authorities. The names
/// are BlueDoc's own wording; categories 8–16 are numbered.
#[must_use]
pub fn toa_category_name(n: u8, vi: bool) -> String {
    let named = match (n, vi) {
        (1, true) => "Bản án và quyết định của tòa án",
        (1, false) => "Court decisions",
        (2, true) => "Luật và bộ luật",
        (2, false) => "Statutes and codes",
        (3, true) => "Tài liệu tham khảo khác",
        (3, false) => "Other sources",
        (4, true) => "Quy tắc và quy chế",
        (4, false) => "Rules",
        (5, true) => "Sách và bình luận pháp lý",
        (5, false) => "Commentaries and treatises",
        (6, true) => "Nghị định và thông tư",
        (6, false) => "Regulations",
        (7, true) => "Hiến pháp",
        (7, false) => "Constitutional provisions",
        _ => "",
    };
    if named.is_empty() {
        if vi {
            format!("Nhóm {n}")
        } else {
            format!("Category {n}")
        }
    } else {
        named.to_owned()
    }
}

/// Number of different pages that turn a citation's page list into "passim" (`TOA \p`).
pub const PASSIM_PAGES: usize = 5;

/// Entries of a TOA field from the TA fields: `TA \l "long" \s "short" \c n` defines a
/// citation, `TA \s "short"` cites it again; `\b` / `\i` bold / italic page number,
/// `\r bookmark` page range. TOA switches: `\c n` category (0 or none: all, grouped by
/// category), `\h` category headings, `\p` "passim" for five or more pages, `\e` / `\l`
/// / `\g` separators, `\b bookmark` (citations inside it).
pub(crate) fn authorities(
    instr: &str,
    marks: &[FieldMark],
    spans: &HashMap<String, (usize, usize)>,
    page: &dyn Fn(usize) -> u32,
    lay: EntryLayout,
    vi: bool,
    styles: &mut Vec<String>,
) -> Vec<Paragraph> {
    let toa = Instr::parse(instr, &["\\b", "\\c", "\\d", "\\e", "\\g", "\\l", "\\s"]);
    let only: u8 = toa
        .get("\\c")
        .and_then(|c| c.trim().parse().ok())
        .unwrap_or(0);
    let within = toa.get("\\b").and_then(|b| spans.get(b)).copied();
    let tas: Vec<(Instr, usize)> = marks
        .iter()
        .filter(|m| field_kind(&m.instr) == "TA")
        .map(|m| (Instr::parse(&m.instr, &["\\c", "\\l", "\\r", "\\s"]), m.pid))
        .collect();
    let cat_of = |ta: &Instr| -> u8 {
        ta.get("\\c")
            .and_then(|c| c.trim().parse().ok())
            .filter(|c| (1..=16).contains(c))
            .unwrap_or(1)
    };
    // Short citation → (long citation, category) of the field that defines it.
    let mut defined: HashMap<String, (String, u8)> = HashMap::new();
    for (ta, _) in &tas {
        if let (Some(l), Some(s)) = (ta.get("\\l"), ta.get("\\s")) {
            defined
                .entry(s.trim().to_lowercase())
                .or_insert_with(|| (l.trim().to_owned(), cat_of(ta)));
        }
    }
    let mut cites: Vec<(u8, String, Vec<Ref>)> = Vec::new();
    for (ta, pid) in &tas {
        if within.is_some_and(|(s, e)| *pid < s || *pid > e) {
            continue;
        }
        let (long, cat) = if let Some(l) = ta.get("\\l") {
            (l.trim().to_owned(), cat_of(ta))
        } else if let Some(s) = ta.get("\\s") {
            defined
                .get(&s.trim().to_lowercase())
                .cloned()
                .unwrap_or_else(|| (s.trim().to_owned(), cat_of(ta)))
        } else {
            continue;
        };
        if long.is_empty() || (only != 0 && cat != only) {
            continue;
        }
        let r = Ref {
            loc: loc_of(ta, *pid, spans, page),
            bold: ta.has("\\b"),
            italic: ta.has("\\i"),
        };
        if let Some(c) = cites.iter_mut().find(|c| c.0 == cat && c.1 == long) {
            c.2.push(r);
        } else {
            cites.push((cat, long, vec![r]));
        }
    }
    cites.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| vi_cmp(&a.1, &b.1)));
    let entry_sep = toa.get("\\e").unwrap_or(", ");
    let list = toa.get("\\l").unwrap_or(", ");
    let range = toa.get("\\g").unwrap_or("\u{2013}");
    let mut out = Vec::new();
    let mut last_cat = 0;
    for (cat, long, refs) in &cites {
        if toa.has("\\h") && *cat != last_cat {
            out.push(entry(
                "TOAHeading",
                plain(&toa_category_name(*cat, vi)),
                lay,
                styles,
            ));
        }
        last_cat = *cat;
        let mut a = plain(long);
        let pages = page_refs(refs);
        if !pages.is_empty() {
            a.extend(plain(entry_sep));
            if toa.has("\\p") && pages.len() >= PASSIM_PAGES {
                a.extend(plain("passim"));
            } else {
                a.extend(pages_atoms(&pages, list, range));
            }
        }
        out.push(entry("TableofAuthorities", a, lay, styles));
    }
    out
}

