/// An index entry to mark (§17.16.5.72 XE).
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct IndexMark {
    /// Main entry.
    pub main: String,
    /// Sub-entry (`main:sub`).
    pub sub: String,
    /// Cross-reference text instead of a page number (`\t`).
    pub cross_ref: String,
    /// Page range: the pages of this bookmark (`\r`).
    pub bookmark: String,
    /// Bold page number (`\b`).
    pub bold: bool,
    /// Italic page number (`\i`).
    pub italic: bool,
}

/// Field text argument: quotes inside are replaced (a field argument cannot hold them).
fn arg(s: &str) -> String {
    s.trim().replace('"', "'")
}

impl IndexMark {
    /// The XE instruction, `None` without a main entry.
    #[must_use]
    pub fn instr(&self) -> Option<String> {
        let main = arg(&self.main).replace(':', " ");
        if main.is_empty() {
            return None;
        }
        let sub = arg(&self.sub);
        let mut s = if sub.is_empty() {
            format!("XE \"{main}\"")
        } else {
            format!("XE \"{main}:{sub}\"")
        };
        let see = arg(&self.cross_ref);
        let bm = self.bookmark.trim();
        if !see.is_empty() {
            s.push_str(&format!(" \\t \"{see}\""));
        } else if !bm.is_empty() && !bm.contains(char::is_whitespace) {
            s.push_str(&format!(" \\r {bm}"));
        }
        if self.bold {
            s.push_str(" \\b");
        }
        if self.italic {
            s.push_str(" \\i");
        }
        Some(s)
    }
}

/// A citation to mark (§17.16.5.62 TA).
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct CitationMark {
    /// Long citation (as listed in the table).
    pub long: String,
    /// Short citation (later mentions); empty: the long one.
    pub short: String,
    /// Category 1–16.
    pub category: u8,
}

impl CitationMark {
    fn short_text(&self) -> String {
        let s = arg(&self.short);
        if s.is_empty() {
            arg(&self.long)
        } else {
            s
        }
    }

    /// The defining TA instruction (`\l`, `\s`, `\c`), `None` without a long citation.
    #[must_use]
    pub fn instr(&self) -> Option<String> {
        let long = arg(&self.long);
        if long.is_empty() {
            return None;
        }
        Some(format!(
            "TA \\l \"{long}\" \\s \"{}\" \\c {}",
            self.short_text(),
            self.category.clamp(1, 16)
        ))
    }

    /// The TA instruction of a later mention (`\s` only).
    #[must_use]
    pub fn short_instr(&self) -> String {
        format!("TA \\s \"{}\"", self.short_text())
    }
}

/// Which notes [`Session::convert_notes`] converts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum NoteConversion {
    /// Footnotes become endnotes.
    ToEndnotes,
    /// Endnotes become footnotes.
    ToFootnotes,
    /// Footnotes and endnotes swap.
    Swap,
}

/// End offset of the first whole-word occurrence of one of `needles` in `text`.
fn find_word(text: &str, needles: &[String]) -> Option<usize> {
    let mut best: Option<(usize, usize)> = None;
    for n in needles.iter().filter(|n| !n.is_empty()) {
        let mut from = 0;
        while let Some(i) = text.get(from..).and_then(|t| t.find(n.as_str())) {
            let s = from + i;
            let e = s + n.len();
            let before = text[..s].chars().next_back();
            let after = text[e..].chars().next();
            if !before.is_some_and(char::is_alphanumeric)
                && !after.is_some_and(char::is_alphanumeric)
            {
                if best.is_none_or(|b| s < b.0) {
                    best = Some((s, e));
                }
                break;
            }
            from = s + n.chars().next().map_or(1, char::len_utf8);
        }
    }
    best.map(|b| b.1)
}

/// The note-reference style of the other kind, or superscript when the document has no
/// such style (§17.3.2.42 vertAlign).
fn note_ref_props(doc: &Document, props: &RunProps, endnote: bool) -> RunProps {
    let (from, to) = if endnote {
        ("FootnoteReference", "EndnoteReference")
    } else {
        ("EndnoteReference", "FootnoteReference")
    };
    let mut p = props.clone();
    if p.style.as_deref() == Some(from) || p.style.as_deref() == Some(to) {
        if doc.style(to).is_some() {
            p.style = Some(to.to_owned());
        } else {
            p.style = None;
            p.vert_align = Some(VertAlign::Superscript);
        }
    }
    p
}

/// Note content moved to the other kind: text and reference styles follow it.
fn convert_note_blocks(doc: &Document, blocks: &[Block], endnote: bool) -> Vec<Block> {
    let (from, to) = if endnote {
        ("FootnoteText", "EndnoteText")
    } else {
        ("EndnoteText", "FootnoteText")
    };
    blocks
        .iter()
        .map(|b| match b {
            Block::Paragraph(p) => {
                let mut q = p.clone();
                if q.props.style.as_deref() == Some(from) {
                    q.props.style = doc.style(to).map(|_| to.to_owned());
                }
                for r in &mut q.runs {
                    if r.content.iter().any(|c| matches!(c, RunContent::NoteMark)) {
                        r.props = note_ref_props(doc, &r.props, endnote);
                    }
                }
                q.src = None;
                Block::Paragraph(q)
            }
            other => other.clone(),
        })
        .collect()
}

impl Session {
    /// Insert a field whose result is a run of paragraphs — a table of contents or of
    /// figures (`TOC`, §17.16.5.68), an index (`INDEX`, §17.16.5.29) or a table of
    /// authorities (`TOA`, §17.16.5.67) — at the caret and fill it. `leader` is the
    /// leader of the right-aligned page numbers; `columns` > 1 puts the field in its own
    /// continuous section with that many columns (§17.6.4 cols, §17.6.22 type).
    pub fn insert_reference_table(
        &mut self,
        instr: &str,
        leader: Option<TabLeader>,
        columns: u16,
        pages_of: &mut dyn FnMut(&Document) -> Vec<u32>,
    ) -> Result<usize> {
        let kind = field_kind(instr);
        if !matches!(kind.as_str(), "TOC" | "INDEX" | "TOA") {
            return Err(EditError::Unsupported(format!(
                "{kind} is not a table field"
            )));
        }
        let mut n = 0;
        let env = self.fields_now();
        self.edit(|tx, sel| {
            let (a, b) = sel.ordered();
            let at = tx.delete_range(a, b)?;
            let paths = tx.paths();
            let path = path_of(tx.doc, &paths, at.para)?;
            if path.len() != 2 {
                return Err(EditError::Unsupported(
                    "reference table inside a table".into(),
                ));
            }
            let p = para_clone(tx.doc, &path)?;
            let len = para_len(&p);
            let (prefix, index) = split_path(&path);
            let insert_at = if at.offset == 0 {
                index
            } else {
                if at.offset < len {
                    tx.split(at)?;
                }
                index + 1
            };
            let si = path[0];
            let mut para_id = if at.offset == 0 { at.para } else { at.para + 1 };
            let width = fields::text_width(tx.doc, si);
            let field = fields::new_block_field_paragraph(instr, leader, width);
            tx.insert_blocks(prefix, insert_at, vec![Block::Paragraph(field)])?;
            if columns > 1 {
                para_id += tx.isolate_in_columns(si, insert_at, columns.min(45))?;
            }
            n = tx.update_fields(pages_of, &env)?;
            let caret = Pos::new(para_id.min(tx.paths().len().saturating_sub(1)), 0);
            Ok(Selection::caret(caret))
        })?;
        self.fix_selection();
        Ok(n)
    }

    /// Mark the selection (or the caret) as an index entry: an XE field after it. `all`
    /// marks the first whole-word occurrence of the selected text in every other
    /// paragraph too. Returns the number of fields inserted.
    pub fn mark_index_entry(&mut self, mark: &IndexMark, all: bool) -> Result<usize> {
        let instr = mark
            .instr()
            .ok_or_else(|| EditError::Unsupported("index entry without text".into()))?;
        let needles = if all {
            self.selected_words()
        } else {
            Vec::new()
        };
        self.mark_with_fields(&instr, &needles, &instr)
    }

    /// Mark the selection as a citation: a defining TA field after it; `all` marks the
    /// other occurrences (of the selected text or the short citation) with `TA \s`.
    pub fn mark_citation(&mut self, mark: &CitationMark, all: bool) -> Result<usize> {
        let instr = mark
            .instr()
            .ok_or_else(|| EditError::Unsupported("citation without text".into()))?;
        let mut needles = if all {
            self.selected_words()
        } else {
            Vec::new()
        };
        if all {
            let s = mark.short_text();
            if !needles.contains(&s) {
                needles.push(s);
            }
        }
        self.mark_with_fields(&instr, &needles, &mark.short_instr())
    }

    /// The selected text when it lies in one paragraph (search text of "mark all").
    fn selected_words(&self) -> Vec<String> {
        let (a, b) = self.selection.ordered();
        if a.para != b.para || a.offset >= b.offset {
            return Vec::new();
        }
        self.para_text(a.para)
            .and_then(|t| t.get(a.offset..b.offset).map(|s| s.trim().to_owned()))
            .filter(|s| !s.is_empty())
            .into_iter()
            .collect()
    }

    fn mark_with_fields(&mut self, instr: &str, needles: &[String], other: &str) -> Result<usize> {
        let (a, b) = self.selection.ordered();
        let mut spots: Vec<(Pos, String)> = vec![(b, instr.to_owned())];
        if !needles.is_empty() {
            let skip = generated_paths(&self.doc);
            for (pid, path) in body_paragraphs(&self.doc).iter().enumerate() {
                if pid == b.para || skip.contains(path) {
                    continue;
                }
                let Some(p) = para_at(&self.doc, path) else {
                    continue;
                };
                // Already marked with the same field: left alone.
                if fields::para_fields(&para::flatten(p))
                    .iter()
                    .any(|(i, _, _)| i == other || i == instr)
                {
                    continue;
                }
                if let Some(end) = find_word(&para_index_text(p), needles) {
                    spots.push((Pos::new(pid, end), other.to_owned()));
                }
            }
        }
        let n = spots.len();
        self.edit(|tx, _| {
            for (pos, ins) in spots {
                let (_, _, atoms) = tx.atoms(pos.para)?;
                let props = para::props_at(&atoms, pos.offset).without_revisions();
                tx.insert_atoms(
                    pos,
                    vec![(
                        RunProps {
                            link: None,
                            ..props
                        },
                        RunContent::Field {
                            instr: ins,
                            cached: String::new(),
                            locked: false,
                            codes: false,
                        },
                    )],
                )?;
            }
            Ok(Selection {
                anchor: a,
                focus: b,
            })
        })?;
        Ok(n)
    }

    /// Convert footnotes to endnotes, endnotes to footnotes or swap them — every note,
    /// or (`selection_only`) the notes referenced inside the selection. Converted notes
    /// get new ids of their new kind; the numbers follow from the reference order
    /// (§17.11.17 footnotePr / §17.11.4 endnotePr numbering). Returns the number of notes
    /// converted (one undo step).
    pub fn convert_notes(&mut self, mode: NoteConversion, selection_only: bool) -> Result<usize> {
        let (a, b) = self.selection.ordered();
        let wants = |endnote: bool| match mode {
            NoteConversion::ToEndnotes => !endnote,
            NoteConversion::ToFootnotes => endnote,
            NoteConversion::Swap => true,
        };
        // Ids -1/0 (and 1 in older files) are separators (§17.11.23).
        let first_free = |m: &std::collections::BTreeMap<i32, Vec<Block>>| {
            m.keys().copied().max().unwrap_or(0).max(1) + 1
        };
        let mut next = [
            first_free(&self.doc.footnotes),
            first_free(&self.doc.endnotes),
        ];
        // (endnote?, old id) → new id of the other kind.
        let mut moved: Vec<((bool, i32), i32)> = Vec::new();
        let mut paras: Vec<(Vec<usize>, Paragraph)> = Vec::new();
        for (pid, path) in body_paragraphs(&self.doc).iter().enumerate() {
            let Some(p) = para_at(&self.doc, path) else {
                continue;
            };
            let mut atoms = para::flatten(p);
            let mut off = 0;
            let mut changed = false;
            for (props, c) in &mut atoms {
                let len = para::atom_len(c);
                let start = Pos::new(pid, off);
                off += len;
                let (endnote, id) = match c {
                    RunContent::FootnoteRef(id) => (false, *id),
                    RunContent::EndnoteRef(id) => (true, *id),
                    _ => continue,
                };
                let inside =
                    !selection_only || (start >= a && Pos::new(pid, start.offset + len) <= b);
                let map = if endnote {
                    &self.doc.endnotes
                } else {
                    &self.doc.footnotes
                };
                if !wants(endnote) || !inside || !map.contains_key(&id) {
                    continue;
                }
                let new_id = if let Some((_, n)) = moved.iter().find(|(k, _)| *k == (endnote, id)) {
                    *n
                } else {
                    let slot = &mut next[usize::from(!endnote)];
                    let n = crate::seeded_id(*slot, self.id_seed);
                    *slot = n + 1;
                    moved.push(((endnote, id), n));
                    n
                };
                *c = if endnote {
                    RunContent::FootnoteRef(new_id)
                } else {
                    RunContent::EndnoteRef(new_id)
                };
                *props = note_ref_props(&self.doc, props, !endnote);
                changed = true;
            }
            if changed {
                let mut q = para::with_atoms(p, atoms);
                q.src = None;
                paras.push((path.clone(), q));
            }
        }
        if moved.is_empty() {
            return Ok(0);
        }
        let mut maps = [self.doc.footnotes.clone(), self.doc.endnotes.clone()];
        for ((endnote, id), new_id) in &moved {
            if let Some(blocks) = maps[usize::from(*endnote)].remove(id) {
                let converted = convert_note_blocks(&self.doc, &blocks, !endnote);
                maps[usize::from(!endnote)].insert(*new_id, converted);
            }
        }
        let [foot, end] = maps;
        let sel = self.selection;
        self.edit(|tx, _| {
            for (endnote, new) in [(false, foot), (true, end)] {
                let old = if endnote {
                    tx.doc.endnotes.clone()
                } else {
                    tx.doc.footnotes.clone()
                };
                if old != new {
                    tx.push(Op::Notes { endnote, old, new })?;
                }
            }
            for (path, p) in paras {
                tx.replace_para(&path, p)?;
            }
            Ok(sel)
        })?;
        Ok(moved.len())
    }
}

/// Paths of the paragraphs that are TOC / INDEX / TOA results.
fn generated_paths(doc: &Document) -> Vec<Vec<usize>> {
    let mut out = Vec::new();
    for (si, s) in doc.sections.iter().enumerate() {
        for t in fields::toc_ranges(&s.blocks) {
            out.extend((t.first..=t.last).map(|bi| vec![si, bi]));
        }
    }
    out
}

impl crate::Tx<'_> {
    /// Put top-level block `bi` of section `si` in a continuous section of its own with
    /// `columns` columns; the blocks after it continue in another continuous section with
    /// the original columns (§17.6.22 type, §17.6.4 cols). Returns how many paragraphs
    /// were added before the block (an empty paragraph ends a part ending in a table).
    fn isolate_in_columns(&mut self, si: usize, bi: usize, columns: u16) -> Result<usize> {
        let old = self
            .doc
            .sections
            .get(si)
            .cloned()
            .ok_or(EditError::BadPath)?;
        let mut parts: Vec<Section> = Vec::new();
        let mut added = 0;
        let mut head = old
            .blocks
            .get(..bi)
            .map(<[Block]>::to_vec)
            .unwrap_or_default();
        let fresh = |blocks: Vec<Block>| Section {
            blocks,
            break_type: SectionBreak::Continuous,
            page_number_start: None,
            headers: HeaderFooter::default(),
            footers: HeaderFooter::default(),
            change: None,
            src: None,
            ..old.clone()
        };
        let mut index = fresh(
            old.blocks
                .get(bi..=bi)
                .map(<[Block]>::to_vec)
                .unwrap_or_default(),
        );
        index.columns.count = columns;
        index.columns.cols.clear();
        if index.columns.space.0 <= 0 {
            index.columns.space = Twips(720);
        }
        if head.is_empty() {
            // The index starts the section: it keeps how the section starts.
            index.break_type = old.break_type;
            index.page_number_start = old.page_number_start;
            index.headers = old.headers.clone();
            index.footers = old.footers.clone();
        } else {
            // §17.6.17: a section's properties go in its last paragraph.
            if !matches!(head.last(), Some(Block::Paragraph(_))) {
                head.push(Block::Paragraph(Paragraph::default()));
                added = 1;
            }
            parts.push(Section {
                blocks: head,
                src: None,
                ..old.clone()
            });
        }
        parts.push(index);
        let mut tail = old
            .blocks
            .get(bi + 1..)
            .map(<[Block]>::to_vec)
            .unwrap_or_default();
        if tail.is_empty() {
            tail.push(Block::Paragraph(Paragraph::default()));
        }
        parts.push(fresh(tail));
        self.push(Op::Sections {
            index: si,
            remove: vec![old],
            insert: parts,
        })?;
        Ok(added)
    }
}

#[cfg(test)]
#[path = "refs_tests.rs"]
mod tests;
